begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(18);
select has_table('public','reservations','reservation header exists');
select has_table('public','reservation_items','snapshot items exist');
select has_table('public','reservation_events','audit events exist');
select ok(coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.reservations')),false),'header RLS');
select ok(coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.reservation_items')),false),'items RLS');
select ok(coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.reservation_events')),false),'events RLS');
select has_function('public','confirm_booking',array['uuid','jsonb'],'narrow confirm RPC');
select has_function('public','list_booking_slots',array['uuid','date','uuid[]','uuid'],'slots RPC');
select ok(not has_table_privilege('authenticated',coalesce(to_regclass('public.reservations'),'public.barbershops'::regclass),'INSERT'),'no direct insert');
select ok(not has_table_privilege('authenticated',coalesce(to_regclass('public.reservations'),'public.barbershops'::regclass),'UPDATE'),'no direct update');
select ok(not exists(select 1 from pg_proc where oid=to_regprocedure('public.confirm_booking(uuid,jsonb)') and (has_function_privilege('authenticated',oid,'EXECUTE') or has_function_privilege('anon',oid,'EXECUTE'))),'ordinary callers cannot confirm');
select ok(exists(select 1 from pg_proc where oid=to_regprocedure('public.confirm_booking(uuid,jsonb)') and not prosecdef and has_function_privilege('service_role',oid,'EXECUTE')),'service wrapper invoker');
select ok(exists(select 1 from pg_constraint where conrelid=to_regclass('public.reservations') and contype='x' and pg_get_constraintdef(oid) like '%barber_user_id WITH =%' and pg_get_constraintdef(oid) like '%confirmed%'),'physical identity exclusion only confirmed');
select ok(exists(select 1 from pg_constraint where conrelid=to_regclass('public.reservations') and contype='u' and pg_get_constraintdef(oid) like '%client_user_id, barbershop_id, request_id%'),'request scoped to owner and shop');
select ok(exists(select 1 from pg_constraint where conrelid=to_regclass('public.reservations') and contype='f' and pg_get_constraintdef(oid) like '%barber_id, barbershop_id, barber_user_id%'),'physical identity cannot be forged');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'reservation_%' and p.prosecdef and not(coalesce(p.proconfig,array[]::text[]) @> array['search_path=""'])),'definers fixed empty search path');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'reservation_%' and p.proname not in('reservation_visible','reservation_slots') and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))),'private helpers closed');
select ok(exists(select 1 from pg_index where indrelid=to_regclass('public.reservations') and pg_get_indexdef(indexrelid) like '%client_user_id, starts_at%'),'owner lookup indexed');
select * from finish();
rollback;
